head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p.data > M > setBroadcast]<br/>전체 DataCollection 의 Broadcast 기능 활성화 여부를 설정합니다.",
    "validation" : [
        "broadCast(필수) 파라미터로 전체 DataCollection 의 Broadcast 기능 활성화 여부를 true/false 로 설정할 수 있어야 합니다.",
        "활성화(true) 상태에서 DataCollection 의 변경 내용이 바인드된 컴포넌트(input, GridView 등)에 즉시 반영되어야 합니다.",
        "비활성화(false) 상태에서 DataCollection 의 변경 내용은 바인드된 컴포넌트에 반영되지 않습니다.",
        "비활성화 → 활성화 로 전환되면 비활성화 상태에서 누적된 변경 내용이 일괄 반영되어야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
    scwin.resetData();
};

// 데이터 초기화 + 항상 활성화 상태로 복원
scwin.resetData = function () {
    $p.data.setBroadcast(true);

    dlt_exam.removeAll();
    dlt_exam.insertRow(0); dlt_exam.setCellData(0, "code", "C0001"); dlt_exam.setCellData(0, "label", "TYPE1");
    dlt_exam.insertRow(1); dlt_exam.setCellData(1, "code", "C0002"); dlt_exam.setCellData(1, "label", "TYPE2");
    dlt_exam.reform();

    dma_exam.set("lang", "ko");
    dma_exam.set("output", "WebSquare");
    dma_exam.reform();

    wf_body_bottom.getObj("scwin").setReturnValue("");
};

scwin.put = function (msg) {
    wf_body_bottom.getObj("scwin").setReturnValue(msg);
};



// 시나리오 1 : 즉시 반영
// broadcast=true 상태에서 데이터 변경 → input / GridView 에 즉시 표시
scwin.btn_immediate_onclick = function () {
    scwin.resetData();
    scwin.put("[즉시 반영] broadcast=true 상태에서 데이터 변경 → input / GridView 에 즉시 반영됩니다.");

    $p.data.setBroadcast(true);

    // DataMap 변경 → ibx_lang / ibx_output 즉시 반영
    dma_exam.set("lang", "en");
    dma_exam.set("output", "BROADCAST_ON");

    // DataList 변경 → grd_exam 셀 즉시 반영
    dlt_exam.setCellData(0, "label", "IMMEDIATE_LBL");
};



// 시나리오 2 : 일괄 반영
// 1) broadcast=false → 데이터 변경 (DOM 미반영)
// 2) 1초 후 broadcast=true → 누적 변경 일괄 반영
scwin.btn_batch_onclick = function () {
    scwin.resetData();
    scwin.put("[일괄 반영] broadcast=false 로 비활성화 후 데이터 변경 → 1초 동안 화면 미반영 (이전 값 유지) → broadcast=true 전환 시 누적 변경이 일괄 반영됩니다.");

    // 1) 비활성화
    $p.data.setBroadcast(false);

    // 2) 누적 변경 (이 시점에는 DOM 미반영)
    dma_exam.set("lang", "BATCH_LANG");
    dma_exam.set("output", "BATCH_OUTPUT");
    dlt_exam.setCellData(0, "label", "BATCH_LBL_0");
    dlt_exam.setCellData(1, "label", "BATCH_LBL_1");

    // 3) 1초 후 활성화 → 누적 변경 일괄 반영
    setTimeout(function () {
        $p.data.setBroadcast(true);
        scwin.put("[일괄 반영] broadcast=true 로 전환 → 누적된 변경 내용이 일괄 반영되었습니다.");
    }, 1000);
};
